import assert from 'node:assert/strict';
import { createTransferWorkspace, createProgressFeed, collectProgressTelemetry } from './src/workspace.js';
const pending = new Map();
const history = [], shown = [], queued = [], records = [], cancels = [], deltas = [];
const feed = createProgressFeed({initialPacket: 'initial', decode: packet => pending.get(packet)?.promise ?? packet});
const workspace = createTransferWorkspace({transport() {}, onCancel: x => cancels.push(x.attemptId), record: x => records.push(x), showQueued: x => queued.push(x), recordProgress: x => history.push(x), showProgress: x => shown.push(x)});
const file = {id: 'a', progressFeed: feed};
workspace.select(file);
assert.deepEqual(shown.map(x => x.frame), ['initial']);
const stopTelemetry = collectProgressTelemetry(feed, x => deltas.push(x));
assert.deepEqual(deltas, []);
for (const name of ['old', 'new']) {
  let resolve;
  const promise = new Promise(r => { resolve = r; });
  pending.set(name, {promise, resolve});
  feed.emit(name);
}
pending.get('new').resolve('new');
await Promise.resolve();
pending.get('old').resolve('old');
await Promise.resolve();
assert.deepEqual(shown.map(x => x.frame), ['initial', 'new']);
assert.deepEqual(history.map(x => x.frame), ['initial', 'new', 'old']);
workspace.retry();
assert.equal(shown.at(-1).attemptId, 2);
assert.equal(records.length, 2);
workspace.hide();
feed.emit('after-hide');
assert.equal(shown.at(-1).frame, 'initial');
assert.equal(deltas.at(-1), 'after-hide');
stopTelemetry();
workspace.select(file);
assert.equal(shown.at(-1).attemptId, 3);
workspace.dispose();
assert.deepEqual(cancels, [1, 2, 3]);
console.log('progress checks passed');
EOF"

